const FRONT_QUAD = [[16.3, 67.9], [554.4, 32.0], [554.4, 408.2], [16.3, 407.4]];
function quadMatrix(w, h, p0, p1, p2, p3) {
  const [x0, y0] = p0, [x1, y1] = p1, [x2, y2] = p2, [x3, y3] = p3;
  const dx1 = x1 - x2, dx2 = x3 - x2, dx3 = x0 - x1 + x2 - x3;
  const dy1 = y1 - y2, dy2 = y3 - y2, dy3 = y0 - y1 + y2 - y3;
  const den = dx1 * dy2 - dx2 * dy1;
  const g = (dx3 * dy2 - dx2 * dy3) / den;
  const hh = (dx1 * dy3 - dx3 * dy1) / den;
  const a = x1 - x0 + g * x1, b = x3 - x0 + hh * x3;
  const d = y1 - y0 + g * y1, e = y3 - y0 + hh * y3;
  return `matrix3d(${a / w},${d / w},0,${g / w},${b / h},${e / h},0,${hh / h},0,0,1,0,${x0},${y0},0,1)`;
}

function makeSvgEl(document) {
  return (tag, attrs, parent) => {
    const el = document.createElementNS("http://www.w3.org/2000/svg", tag);
    for (const k in attrs) el.setAttribute(k, attrs[k]);
    parent.appendChild(el);
    return el;
  };
}

function buildBacks(document, svgEl) {
  // Back screens: project each flat card onto its quad inside #backs (coords from the Figma masks)
  // Each back screen is the front quad scaled down about its right-edge centre and pushed right,
  // so it sits lower, smaller and further back than the one in front of it.
  const depth = (s, dx) => FRONT_QUAD.map(([x, y]) => [554.4 + s * (x - 554.4) + dx, 220 + s * (y - 220)]);
  document.getElementById("bc-mid").style.transform = quadMatrix(1670, 1170, ...depth(0.92, 30));
  document.getElementById("bc-far").style.transform = quadMatrix(1670, 1170, ...depth(0.84, 56));

  const pen = '<svg class="ic" viewBox="0 0 24 24"><path d="M4 20h4L19 9l-4-4L4 16v4z" /></svg>';
  const usr = '<svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="8" r="3.5" /><path d="M5 20a7 7 0 0 1 14 0" /></svg>';
  const services = [
    ["Emergency Room Visit", "Dec 2, 2025, 03:14 PM", 3, 5, true], ["Preop Diagnostic Testing", "Nov 28, 2025, 05:22 PM", 1, 4, true],
    ["COVID-19 Diagnostic Testing", "Nov 28, 2025, 05:18 PM", 1, 3, true], ["Dialysis", "Dec 5, 2025, 10:47 AM", 1, 3, true],
    ["Anesthesia", "Nov 28, 2025, 05:11 PM", 1, 2, true], ["Skilled Nursing Facility", "Dec 5, 2025, 11:02 AM", 1, 3, true],
    ["Durable Medical Equipment", "Nov 28, 2025, 04:58 PM", 2, 2, true], ["Outpatient Surgery", "Dec 2, 2025, 03:31 PM", 2, 4, true],
    ["Radiology", "Nov 28, 2025, 05:02 PM", 2, 3, true], ["Ambulance Transportation", "Nov 28, 2025, 04:55 PM", 1, 2, false],
  ];
  const parts = [["Professional Component", "PPG", "g", 5], ["Facility Component", "HOSPITAL", "p", 4], ["Out Of Area", "PLAN", "s", 4]];
  document.getElementById("bc-rows").innerHTML = services.map(([name, at, comps, filters, on], i) =>
    `<div class="bc-tr"><div class="bc-svc"><span class="bc-chev">${i ? "›" : "⌄"}</span><span class="bc-plus">+</span><div><b>${name}</b><small>Modified At: ${at}</small></div></div>
      <span class="bc-mono">${comps} component${comps > 1 ? "s" : ""}</span><span class="bc-num">1</span><span class="bc-num">${filters}</span>
      <div class="bc-act"><span>${pen}</span><span>${usr}</span></div><div class="bc-st">${on ? "Enabled" : "Disabled"}<span class="bc-tog${on ? "" : " off"}"></span></div></div>` +
    (i ? "" : parts.map(([p, tag, c, f]) =>
      `<div class="bc-tr sub"><div class="bc-svc" style="padding-left:74px"><span class="bc-chip">${p}</span><span class="bc-tag ${c}">${tag}</span></div>
        <span class="bc-muted">component</span><span class="bc-num bc-muted">Default</span><span class="bc-num">${f}</span><span class="bc-link">View filters</span><span></span></div>`).join(""))
  ).join("");

  // Decision tree (SVG)
  const tree = document.getElementById("bc-tree-svg");
  const node = (cx, y, w, kind, label) => {
    const k = { service: ["#1f2bff", "none", "SERVICE"], group: ["#121a33", "none", "RULE GROUP"], comp: ["#4b5bff", "none", "COMPONENT"],
      field: ["#fff", "#2f6f6a", "FIELD"], formula: ["#6d28d9", "none", "FORMULA"] }[kind];
    const x = cx - w / 2, light = kind === "field";
    svgEl("rect", { x, y, width: w, height: 56, rx: 8, fill: k[0], stroke: k[1], "stroke-width": 1.5 }, tree);
    svgEl("rect", { x: x + 12, y: y + 9, width: k[2].length * 7 + 12, height: 16, rx: 3, fill: light ? "#e6f1f0" : "rgba(255,255,255,0.92)" }, tree);
    svgEl("text", { x: x + 18, y: y + 21, "font-size": 10, "font-weight": 700, fill: light ? "#2f6f6a" : k[0], "letter-spacing": "0.06em" }, tree).textContent = k[2];
    svgEl("text", { x: x + 12, y: y + 44, "font-size": 15, "font-weight": 600, fill: light ? "#0e1726" : "#fff" }, tree).textContent = label;
  };
  const wire = (x1, y1, x2, y2, color = "#c3c9d4") => svgEl("path", { d: `M${x1},${y1} L${x2},${y2}`, stroke: color, "stroke-width": 2, fill: "none" }, tree);
  const pill = (cx, y, text, ok) => {
    svgEl("rect", { x: cx - 42, y, width: 84, height: 28, rx: 14, fill: ok ? "#e9f7ef" : "#fdecec", stroke: ok ? "#2f9e5b" : "#e5484d", "stroke-width": 1.5 }, tree);
    svgEl("text", { x: cx, y: y + 19, "text-anchor": "middle", "font-size": 13, "font-weight": 700, fill: ok ? "#1d7a45" : "#c0262d" }, tree).textContent = text;
  };
  const cols = [260, 704, 1148];
  wire(704, 76, 704, 112, "#3d4bff");
  cols.forEach((cx) => svgEl("path", { d: `M704,168 C704,200 ${cx},190 ${cx},222`, stroke: "#3d4bff", "stroke-width": 2, fill: "none" }, tree));
  node(704, 20, 250, "service", "Emergency Room Visit");
  node(704, 112, 220, "group", "Default");
  [["Professional Component", [["field", "Place of service"], ["#2307", 1], ["field", "Billing Provider Address Zip"], ["#2310", 0], ["formula", "Distance between two locations"]]],
   ["Facility Component", [["field", "Place of service"], ["#2308", 1], ["field", "Revenue code"], ["#2309", 1], ["field", "Billing Provider Address Zip"]]],
   ["Out Of Area", [["field", "Place of service"], ["#2307", 1], ["field", "Billing Provider Address Zip"], ["#2310", 0]]],
  ].forEach(([comp, steps], c) => {
    const cx = cols[c];
    let y = 222;
    node(cx, y, 260, "comp", comp);
    y += 56;
    steps.forEach(([a, b]) => {
      if (a.startsWith("#")) { wire(cx, y, cx, y + 14, b ? "#2f9e5b" : "#e5484d"); pill(cx, y + 14, a, b); wire(cx, y + 42, cx, y + 58, b ? "#2f9e5b" : "#e5484d"); y += 58; }
      else { wire(cx, y, cx, y + 26); node(cx, y + 26, 260, a, b); y += 82; }
    });
  });

}

// Number formatting for count-ups
const fmt = (el, v) => {
  const dec = +(el.dataset.dec || 0);
  if (el.dataset.fmt === "hm") { const m = Math.round(v); return `${Math.floor(m / 60)}h ${m % 60}m`; }
  return v.toLocaleString("en-US", { minimumFractionDigits: dec, maximumFractionDigits: dec }) + (el.dataset.suffix || "");
};
const countUp = (tl, el, at, dur) => {
  const o = { v: 0 }, to = +el.dataset.count;
  tl.fromTo(o, { v: 0 }, { v: to, duration: dur, ease: "power2.out",
    onUpdate: () => { el.textContent = fmt(el, el.dataset.dec ? o.v : Math.round(o.v)); } }, at);
};


function sceneEntrance(tl, q) {
  // 1. Front dashboard settles in, then the two screens behind it slide out from underneath
  tl.fromTo(q("#dash"), { opacity: 0 }, { opacity: 1, duration: 0.9, ease: "power2.out" }, 0.15);
  tl.fromTo(q("#dash-inner"), { y: 46 }, { y: 0, duration: 1.3 }, 0.15);
  tl.fromTo(q("#card-mid"), { x: -50, opacity: 0 }, { x: 0, opacity: 1, duration: 1.3 }, 0.8);
  tl.fromTo(q("#card-back"), { x: -95, opacity: 0 }, { x: 0, opacity: 1, duration: 1.4 }, 0.95);

}

function sceneSheen(tl, q) {
  tl.fromTo(q("#sheen"), { xPercent: -120, opacity: 1 }, { xPercent: 300, opacity: 1, duration: 1.8, ease: "power2.inOut" }, 4.6);
}

