// Shared chrome animation for u-kit screens: sidebar stagger + active pill sweep.
function chromeIn(tl, q) {
  tl.fromTo(q(".u-sb"), { x: -16, opacity: 0 }, { x: 0, opacity: 1, duration: 0.6, stagger: 0.04 }, 0.55);
  tl.fromTo(q(".u-nav-bg"), { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: 0.7, ease: "power3.inOut" }, 0.9);
  tl.fromTo(q(".u-foot > *"), { y: 10, opacity: 0 }, { y: 0, opacity: 1, duration: 0.6, stagger: 0.08 }, 1.0);
}

// Smooth Catmull-Rom path through points.
function smoothPath(pts) {
  let d = `M${pts[0][0]},${pts[0][1]}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;
    d += ` C${p1[0] + (p2[0] - p0[0]) / 6},${p1[1] + (p2[1] - p0[1]) / 6} ${p2[0] - (p3[0] - p1[0]) / 6},${p2[1] - (p3[1] - p1[1]) / 6} ${p2[0]},${p2[1]}`;
  }
  return d;
}

